-- Name: award_club_points(uuid, integer, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_club_points(p_user_id uuid, p_points integer, p_action text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_coins integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Insert points entry
  VALUES (p_user_id, p_points, p_action, p_reference, p_notes);

  -- Credit coins if applicable
  IF p_coins > 0 THEN
    PERFORM public.credit_coins(
      p_user_id,
      p_coins,
      'club_reward',
      COALESCE(p_notes, 'Club: ' || p_action)
    );
  END IF;
END;
$$;


