--
-- Name: fn_sync_form_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_form_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Only fire when state column actually changes
  IF OLD.profile_state IS DISTINCT FROM NEW.profile_state THEN
    UPDATE people_records
    SET
      form_submission_state = NEW.profile_state,
      form_submitted_at     = CASE WHEN NEW.profile_state = 'submitted'  THEN NEW.submitted_at ELSE form_submitted_at END,
      form_verified_at      = CASE WHEN NEW.profile_state = 'verified'   THEN NEW.verified_at  ELSE form_verified_at  END
    WHERE user_id = NEW.user_id;

    -- Also advance onboarding_state if it's still at 'activated'
    UPDATE users
    SET onboarding_state =
      CASE
        WHEN NEW.profile_state = 'submitted' AND onboarding_state IN ('invited','activated') THEN 'profile_submitted'
        WHEN NEW.profile_state = 'verified'  THEN 'complete'
        ELSE onboarding_state
      END
    WHERE id = NEW.user_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_sync_onboarding_from_profile_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_onboarding_from_profile_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.profile_state = 'draft' then
    update public.people_records
    set onboarding = jsonb_set(
      coalesce(onboarding, '{}'::jsonb),
      '{profile_draft}',
      'true'::jsonb,
      true
    )
    where user_id = new.user_id;

  elsif new.profile_state = 'submitted' then
    update public.people_records
    set onboarding = jsonb_set(
      jsonb_set(
        coalesce(onboarding, '{}'::jsonb),
        '{profile_draft}',
        'false'::jsonb,
        true
      ),
      '{profile_published}',
      'true'::jsonb,
      true
    )
    where user_id = new.user_id;
  end if;

  return new;
end;
$$;


--
-- Name: get_club_rank(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_club_rank(p_points integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF p_points >= 1000 THEN RETURN 'Growth Partner';
  ELSIF p_points >= 400 THEN RETURN 'Operator';
  ELSIF p_points >= 100 THEN RETURN 'Builder';
  ELSE RETURN 'Rookie';
  END IF;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_full_name TEXT;
  v_email     TEXT;
BEGIN
  v_email     := NEW.email;
  v_full_name := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    split_part(NEW.email, '@', 1)
  );

  -- Create profile
  VALUES (NEW.id, v_email, v_full_name, NOW(), NOW())
  ON CONFLICT (id) DO NOTHING;

  -- Initialise coin balance
  VALUES (NEW.id, 0, 0)
  ON CONFLICT (user_id) DO NOTHING;

  -- Credit 70 signup coins (no expiry — Phase 1 model)
  PERFORM public.credit_coins(
    NEW.id,
    70,
    'signup_bonus',
    '70 free Cerebre Coins — welcome gift'
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: recompute_goal_velocity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_goal_velocity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  krs          JSONB;
  total_krs    INT;
  achieved_krs INT;
  sum_pct      NUMERIC;
  progress     INT;
  new_status   TEXT;
  velocity_ratio NUMERIC;
BEGIN
  krs := NEW.key_results;

  -- If no key results exist, leave status unchanged
  IF krs IS NULL OR jsonb_array_length(krs) = 0 THEN
    RETURN NEW;
  END IF;

  total_krs    := jsonb_array_length(krs);
  achieved_krs := 0;
  sum_pct      := 0;

  FOR i IN 0 .. total_krs - 1 LOOP
    DECLARE
      kr         JSONB := krs -> i;
      current_v  NUMERIC := COALESCE((kr->>'current_value')::NUMERIC, 0);
      target_v   NUMERIC := COALESCE((kr->>'target_value')::NUMERIC, 1);
      pct        NUMERIC;
    BEGIN
      pct := LEAST(current_v / NULLIF(target_v, 0), 1) * 100;
      sum_pct := sum_pct + pct;
      IF current_v >= target_v THEN achieved_krs := achieved_krs + 1; END IF;
    END;
  END LOOP;

  progress := (sum_pct / total_krs)::INT;

  -- Determine velocity-based status
  IF achieved_krs = total_krs THEN
    new_status := 'achieved';
  ELSIF progress >= 60 THEN
    new_status := 'on_track';
  ELSE
    new_status := 'at_risk';
  END IF;

  NEW.current_progress := progress;
  NEW.status           := new_status;
  NEW.updated_at       := NOW();

  RETURN NEW;
END;
$$;


