--
-- Name: v_annual_revenue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_annual_revenue AS
 SELECT (EXTRACT(year FROM i.paid_date))::integer AS year,
    i.invoice_type,
    i.brand_id,
    b.name AS brand_name,
    count(DISTINCT i.id) AS invoice_count,
    sum(i.amount) AS total_received
   FROM (public.invoices i
     JOIN public.brands b ON ((b.id = i.brand_id)))
  WHERE (((i.status)::text = 'paid'::text) AND (i.paid_date IS NOT NULL))
  GROUP BY ((EXTRACT(year FROM i.paid_date))::integer), i.invoice_type, i.brand_id, b.name;


--
-- Name: v_invoice_aging; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_invoice_aging AS
 WITH payments_by_invoice AS (
         SELECT p.invoice_id,
            sum(p.amount) AS amount_paid
           FROM public.payments p
          GROUP BY p.invoice_id
        )
 SELECT i.brand_id,
    b.name AS brand_name,
    COALESCE(sum(
        CASE
            WHEN (i.due_date >= CURRENT_DATE) THEN (i.amount - COALESCE(pbi.amount_paid, (0)::numeric))
            ELSE NULL::numeric
        END), (0)::numeric) AS current_outstanding,
    COALESCE(sum(
        CASE
            WHEN ((i.due_date < CURRENT_DATE) AND (((CURRENT_DATE - i.due_date) >= 1) AND ((CURRENT_DATE - i.due_date) <= 7))) THEN (i.amount - COALESCE(pbi.amount_paid, (0)::numeric))
            ELSE NULL::numeric
        END), (0)::numeric) AS overdue_0_7,
    COALESCE(sum(
        CASE
            WHEN ((i.due_date < CURRENT_DATE) AND (((CURRENT_DATE - i.due_date) >= 8) AND ((CURRENT_DATE - i.due_date) <= 30))) THEN (i.amount - COALESCE(pbi.amount_paid, (0)::numeric))
            ELSE NULL::numeric
        END), (0)::numeric) AS overdue_8_30,
    COALESCE(sum(
        CASE
            WHEN ((i.due_date < CURRENT_DATE) AND (((CURRENT_DATE - i.due_date) >= 31) AND ((CURRENT_DATE - i.due_date) <= 60))) THEN (i.amount - COALESCE(pbi.amount_paid, (0)::numeric))
            ELSE NULL::numeric
        END), (0)::numeric) AS overdue_31_60,
    COALESCE(sum(
        CASE
            WHEN ((i.due_date < CURRENT_DATE) AND ((CURRENT_DATE - i.due_date) > 60)) THEN (i.amount - COALESCE(pbi.amount_paid, (0)::numeric))
            ELSE NULL::numeric
        END), (0)::numeric) AS overdue_60_plus,
    COALESCE(sum((i.amount - COALESCE(pbi.amount_paid, (0)::numeric))), (0)::numeric) AS total_outstanding,
    count(*) FILTER (WHERE ((i.status)::text <> ALL ((ARRAY['paid'::character varying, 'cancelled'::character varying])::text[]))) AS open_invoice_count
   FROM ((public.invoices i
     JOIN public.brands b ON ((b.id = i.brand_id)))
     LEFT JOIN payments_by_invoice pbi ON ((pbi.invoice_id = i.id)))
  WHERE ((i.status)::text <> ALL ((ARRAY['paid'::character varying, 'cancelled'::character varying, 'draft'::character varying])::text[]))
  GROUP BY i.brand_id, b.name;


--
-- Name: v_profile_form_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_profile_form_summary AS
 SELECT pr.user_id,
    pr.display_name,
    pr.role_title,
    pr.department,
    pr.employment_type,
    pr.start_date,
    pr.form_submission_state,
    pr.form_submitted_at,
    pr.form_verified_at,
    pr.guarantor_form_received,
    sps.profile_state,
    sps.surname,
    sps.first_name,
    sps.phone,
    sps.personal_email,
    sps.nok_name,
    sps.nok_phone,
    sps.total_years_experience,
    sps.guarantor_name,
    sps.guarantor_phone,
    sps.guarantor_form_acknowledged,
    sps.digital_signature,
    sps.signature_date,
    sps.hr_notes,
    sps.created_at AS form_started_at,
    sps.updated_at AS form_last_saved
   FROM (public.people_records pr
     LEFT JOIN public.staff_profile_submissions sps ON ((sps.user_id = pr.user_id)))
  WHERE ((pr.status)::text = 'active'::text);


--
-- Name: VIEW v_profile_form_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_profile_form_summary IS 'HR dashboard view: profile form completion status without Tier-3 fields. Medical data must be read via the service layer (triggers audit log).';


--
-- Name: v_revenue_actuals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_revenue_actuals AS
 SELECT (EXTRACT(year FROM p.payment_date))::integer AS year,
    (EXTRACT(quarter FROM p.payment_date))::integer AS quarter,
    (EXTRACT(month FROM p.payment_date))::integer AS month,
    i.invoice_type,
    sum(p.amount) AS amount
   FROM (public.payments p
     JOIN public.invoices i ON ((i.id = p.invoice_id)))
  GROUP BY (EXTRACT(year FROM p.payment_date)), (EXTRACT(quarter FROM p.payment_date)), (EXTRACT(month FROM p.payment_date)), i.invoice_type;


--
-- Name: v_vat_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_vat_summary AS
 SELECT (EXTRACT(year FROM issued_date))::integer AS year,
    (EXTRACT(quarter FROM issued_date))::integer AS quarter,
    (EXTRACT(month FROM issued_date))::integer AS month,
    brand_id,
    count(*) AS invoice_count,
    sum(amount) AS gross_amount
   FROM public.invoices i
  WHERE ((status)::text <> ALL ((ARRAY['cancelled'::character varying, 'draft'::character varying])::text[]))
  GROUP BY ((EXTRACT(year FROM issued_date))::integer), ((EXTRACT(quarter FROM issued_date))::integer), ((EXTRACT(month FROM issued_date))::integer), brand_id;


--
-- Name: vacancies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vacancies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    role_name character varying(120) NOT NULL,
    department character varying(64),
    description text,
    date_opened date DEFAULT CURRENT_DATE NOT NULL,
    date_filled date,
    status character varying(16) DEFAULT 'open'::character varying NOT NULL,
    created_by uuid,
    filled_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vacancies_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'filled'::character varying, 'cancelled'::character varying])::text[])))
);


--
-- Name: TABLE vacancies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vacancies IS 'Open position tracker. HR creates/fills vacancies. MD dashboard shows count of open vacancies. Feeds HR and Workforce goal category in Agency Goals.';


--
-- Name: weekly_ratings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_ratings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rater_id uuid NOT NULL,
    staff_id uuid NOT NULL,
    brand_id uuid NOT NULL,
    week_start date NOT NULL,
    score smallint NOT NULL,
    note text,
    is_creative_of_week boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT weekly_ratings_score_check CHECK (((score >= 1) AND (score <= 5)))
);


--
-- Name: weekly_report_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_report_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    brand_id uuid NOT NULL,
    brand_admin_id uuid NOT NULL,
    aria_draft_payment text,
    edited_payment text,
    aria_draft_achievements text,
    edited_achievements text,
    aria_draft_todos text,
    edited_todos text,
    aria_draft_goals text,
    edited_goals text,
    aria_draft_social text,
    edited_social text,
    aria_draft_pipeline text,
    edited_pipeline text,
    aria_generated_at timestamp with time zone,
    is_submitted boolean DEFAULT false,
    submitted_at timestamp with time zone,
    brand_admin_notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: weekly_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    week_start date NOT NULL,
    week_end date NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: weekly_scores; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weekly_scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    score_type character varying(20) NOT NULL,
    week_start date NOT NULL,
    components jsonb DEFAULT '{}'::jsonb NOT NULL,
    total numeric(5,2) NOT NULL,
    excluded boolean DEFAULT false,
    computed_at timestamp with time zone DEFAULT now(),
    CONSTRAINT weekly_scores_score_type_check CHECK (((score_type)::text = ANY ((ARRAY['staff'::character varying, 'brand_admin'::character varying])::text[])))
);


--
-- Name: weekly_submission_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.weekly_submission_status AS
 SELECT wr.id AS report_id,
    wr.week_start,
    wr.week_end,
    u.id AS brand_admin_id,
    u.full_name AS brand_admin_name,
    b.id AS brand_id,
    b.name AS brand_name,
    wre.id AS entry_id,
    wre.is_submitted,
    wre.submitted_at,
    wre.aria_generated_at,
        CASE
            WHEN (wre.id IS NULL) THEN 'not_started'::text
            WHEN wre.is_submitted THEN 'submitted'::text
            WHEN (wre.aria_generated_at IS NOT NULL) THEN 'draft'::text
            ELSE 'not_started'::text
        END AS status
   FROM ((((public.weekly_reports wr
     CROSS JOIN ( SELECT DISTINCT u_1.id,
            u_1.full_name
           FROM public.users u_1
          WHERE (u_1.role = ANY (ARRAY['brand_admin'::text, 'admin'::text]))) u)
     JOIN public.brand_users bu ON ((bu.user_id = u.id)))
     JOIN public.brands b ON ((b.id = bu.brand_id)))
     LEFT JOIN public.weekly_report_entries wre ON (((wre.report_id = wr.id) AND (wre.brand_id = b.id) AND (wre.brand_admin_id = u.id))))
  ORDER BY u.full_name, b.name;


--
-- Name: work_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand_id uuid NOT NULL,
    user_id uuid NOT NULL,
    goal_id uuid,
    category character varying(50) NOT NULL,
    title text NOT NULL,
    description text,
    hours numeric(5,1) DEFAULT 0,
    evidence_files jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    strategy_id uuid,
    proof_links jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT work_logs_category_check CHECK (((category)::text = ANY ((ARRAY['strategy'::character varying, 'content_copy'::character varying, 'design'::character varying, 'social_media'::character varying, 'analytics'::character varying, 'video'::character varying, 'community'::character varying, 'client_comms'::character varying, 'ads'::character varying, 'seo'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT work_logs_hours_check CHECK ((hours >= (0)::numeric))
);


