--
-- Name: brand_users brand_users_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY brand_users_delete ON public.brand_users FOR DELETE USING ((EXISTS ( SELECT 1
   FROM public.brand_users bu
  WHERE ((bu.brand_id = brand_users.brand_id) AND (bu.user_id = COALESCE((current_setting('app.current_user'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) AND ((bu.role)::text = 'brand_admin'::text) AND ((bu.status)::text = 'active'::text)))));


--
-- Name: brand_users brand_users_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY brand_users_insert ON public.brand_users FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM public.brand_users bu
  WHERE ((bu.brand_id = brand_users.brand_id) AND (bu.user_id = COALESCE((current_setting('app.current_user'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) AND ((bu.role)::text = 'brand_admin'::text) AND ((bu.status)::text = 'active'::text)))));


--
-- Name: brand_users brand_users_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY brand_users_select ON public.brand_users FOR SELECT USING (((user_id = COALESCE((current_setting('app.current_user'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) OR (EXISTS ( SELECT 1
   FROM public.brand_users bu
  WHERE ((bu.brand_id = brand_users.brand_id) AND (bu.user_id = COALESCE((current_setting('app.current_user'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) AND ((bu.role)::text = 'brand_admin'::text) AND ((bu.status)::text = 'active'::text))))));


--
-- Name: brand_users brand_users_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY brand_users_update ON public.brand_users FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM public.brand_users bu
  WHERE ((bu.brand_id = brand_users.brand_id) AND (bu.user_id = COALESCE((current_setting('app.current_user'::text, true))::uuid, '00000000-0000-0000-0000-000000000000'::uuid)) AND ((bu.role)::text = 'brand_admin'::text) AND ((bu.status)::text = 'active'::text)))));


